package com.gameaggregator.webhookservice.application;import com.gameaggregator.webhookservice.domain.*;import com.gameaggregator.webhookservice.infrastructure.*;import java.time.Instant;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;@Component public class WebhookWorker{final WebhookDeliveryRepository deliveries;final WebhookEndpointRepository endpoints;final WebhookAttemptRepository attempts;final WebhookSender sender;public WebhookWorker(WebhookDeliveryRepository d,WebhookEndpointRepository e,WebhookAttemptRepository a,WebhookSender s){deliveries=d;endpoints=e;attempts=a;sender=s;}@Scheduled(fixedDelayString="${webhook.worker.delay-ms:1000}")@Transactional public void deliver(){for(var d:deliveries.findTop50ByStatusAndNextAttemptAtLessThanEqualOrderByNextAttemptAtAsc("PENDING",Instant.now())){var endpoint=endpoints.findById(d.endpointId).orElse(null);if(endpoint==null||!endpoint.active){d.attemptCount++;fail(d,null,"Endpoint is inactive",0);continue;}int number=d.attemptCount+1;try{int status=sender.send(endpoint,d.eventId,d.payload);attempts.save(new WebhookAttempt(d.id,number,status,null));d.attemptCount=number;d.lastHttpStatus=status;if(status>=200&&status<300){d.status="DELIVERED";d.deliveredAt=Instant.now();d.lastError=null;}else fail(d,status,"HTTP "+status,endpoint.maxRetries);}catch(Exception e){attempts.save(new WebhookAttempt(d.id,number,null,e.getMessage()));d.attemptCount=number;fail(d,null,e.getMessage(),endpoint.maxRetries);}}}private void fail(WebhookDelivery d,Integer status,String error,int maxRetries){d.lastHttpStatus=status;d.lastError=error;if(d.attemptCount>maxRetries){d.status="DEAD_LETTER";}else{d.status="PENDING";long delay=Math.min(3600,1L<<Math.min(20,d.attemptCount));d.nextAttemptAt=Instant.now().plusSeconds(delay);}}}